import { cn } from '@/lib/utils'

export const Lights: React.FC<{ className?: string }> = ({ className }) => (
  <div className={cn('w-full h-full overflow-hidden', className)}>
    <div
      className={'w-full h-full relative bottom-[-200px] '}
      style={{
        background:
          'conic-gradient(from 180deg at 50% 50%,var(--color-blue-500) 0deg,var(--color-cyan-400) 180deg,var(--color-yellow-400) 1turn)',
        filter: 'blur(75px)',
        opacity: '20%'
      }}
    />
  </div>
)
